using DevExpress.XtraReports.UI;
using System;
using System.Collections.Generic;
using System.Linq;

namespace SisFa.Pages.Opening.FABCTGTH1.VN
{
    public partial class FABCTGTH1 : DevExpress.XtraReports.UI.XtraReport
    {
        // Khai báo biến lưu mảng tên cột động (L_L01, L_L02...)
        private string[] ListDetail;
        private int n_cot;

        public FABCTGTH1()
        {
            InitializeComponent();

            // 1. VÔ HIỆU HÓA SCRIPT CŨ CỦA WINFORM (Tránh gây lỗi ngầm)
            this.ScriptsSource = "";
            this.Scripts.OnBeforePrint = "";
            this.DetailReport.Scripts.OnBeforePrint = "";

            // 2. ĐĂNG KÝ SỰ KIỆN VẼ CỘT MỚI CHO BLAZOR
            this.BeforePrint += Report_BeforePrint;

            // Xóa script cũ và đăng ký sự kiện cho các ô tiêu đề cột & ô dữ liệu
            XRTableCell[] dataCells = { tableCell5, tableCell7, tableCell12, tableCell9, tableCell15, tableCell16, tableCell17, tableCell20, tableCell18 };
            for (int i = 0; i < dataCells.Length; i++)
            {
                dataCells[i].Scripts.OnBeforePrint = "";
                int colIndex = i; // Bắt buộc lưu index để truyền vào lambda
                dataCells[i].BeforePrint += (s, e) => BindDataCell(s, colIndex);
            }

            // Xử lý riêng cho cột "Chỉ tiêu" (tableCell11) để in đậm các dòng tổng cộng
            tableCell11.Scripts.OnBeforePrint = "";
            tableCell11.BeforePrint += (s, e) =>
            {
                var row = DetailReport.GetCurrentRow() as FABCTGTH1Row;
                var cell = s as XRTableCell;
                if (row != null && cell != null)
                {
                    if (row.bold == 1)
                        cell.Font = new System.Drawing.Font(cell.Font, System.Drawing.FontStyle.Bold);
                    else
                        cell.Font = new System.Drawing.Font(cell.Font, System.Drawing.FontStyle.Regular);
                }
            };
        }

        // --- HÀM 1: ĐỌC TIÊU ĐỀ CỘT TỪ MODEL VÀ VẼ LÊN HEADER BÁO CÁO ---
        private void Report_BeforePrint(object sender, System.ComponentModel.CancelEventArgs e)
        {
            // Lấy DataSource dưới dạng danh sách Model của Blazor
            var ds = this.DataSource as IEnumerable<FABCTGTH1Model>;
            var model = ds?.FirstOrDefault();

            if (model != null)
            {
                string strTenCot = model.v_title_report ?? "";
                string strDetail = model.value_detail_report ?? "";

                // Tách chuỗi thành mảng (Ngăn cách bằng dấu chấm phẩy)
                var listTenCot = strTenCot.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);
                ListDetail = strDetail.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);
                n_cot = ListDetail.Length;

                // Map 9 Tiêu đề cột tương ứng (Từ tbCell1 đến tbCell9)
                XRTableCell[] headerCells = { tbCell1, tbCell2, tbCell3, tbCell4, tbCell5, tbCell6, tbCell7, tbCell8, tbCell9 };
                for (int i = 0; i < headerCells.Length; i++)
                {
                    if (i < listTenCot.Length)
                        headerCells[i].Text = listTenCot[i].Trim().ToUpper();
                    else
                        headerCells[i].Text = "";
                }
            }
        }

        // --- HÀM 2: MÓC NỐI (BINDING) CỘT L_L01, L_L02... VÀO TỪNG Ô DỮ LIỆU ---
        private void BindDataCell(object sender, int colIndex)
        {
            XRTableCell cell = sender as XRTableCell;
            if (cell == null) return;

            if (ListDetail != null && colIndex < n_cot)
            {
                string fieldName = ListDetail[colIndex].Trim();

                // Lấy dòng dữ liệu Model hiện tại đang chạy
                var currentRow = DetailReport.GetCurrentRow() as FABCTGTH1Row;
                if (currentRow != null)
                {
                    // Sử dụng Reflection của C# để lấy giá trị biến động (L_L01, L_L02...)
                    var prop = currentRow.GetType().GetProperty(fieldName);
                    if (prop != null)
                    {
                        var value = prop.GetValue(currentRow);
                        // Tự động ẩn số 0 và định dạng dấu phẩy (N0)
                        if (value != null && decimal.TryParse(value.ToString(), out decimal numVal) && numVal != 0)
                        {
                            cell.Text = string.Format("{0:N0}", numVal);
                        }
                        else
                        {
                            cell.Text = ""; 
                        }
                    }
                }
            }
            else
            {
                cell.Text = ""; // Nếu không có cột dữ liệu thì để trống
            }

            // Xử lý bôi đậm cho các dòng có cờ bold = 1 (Ví dụ: I. Nguyên giá TSCĐ)
            var row = DetailReport.GetCurrentRow() as FABCTGTH1Row;
            if (row != null && row.bold == 1)
                cell.Font = new System.Drawing.Font(cell.Font, System.Drawing.FontStyle.Bold);
            else
                cell.Font = new System.Drawing.Font(cell.Font, System.Drawing.FontStyle.Regular);
        }
    }
}
